1	import webpush from "web-push";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { resolveNotificationRecipients } from "./notification-prefs";
4	
5	/**
6	 * v2 notification dispatch. Reuses the shared web-push machinery (same VAPID keys
7	 * + the same /public/sw.js payload shape { title, body, data }) but writes to the
8	 * v2-owned tables. Producers (chat, gallery, etc.) call these server-side with a
9	 * service-role client. Best-effort: push failures never throw.
10	 */
11	
12	if (
13	  process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY &&
14	  process.env.VAPID_PRIVATE_KEY &&
15	  process.env.VAPID_SUBJECT
16	) {
17	  webpush.setVapidDetails(
18	    process.env.VAPID_SUBJECT,
19	    process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY,
20	    process.env.VAPID_PRIVATE_KEY,
21	  );
22	}
23	
24	export interface V2NotificationInput {
25	  orgId: string;
26	  type: string;
27	  title: string;
28	  body?: string;
29	  /** data.url is an in-app path the shared service worker navigates to on click. */
30	  data?: Record<string, unknown>;
31	}
32	
33	async function pushToUser(
34	  admin: SupabaseClient,
35	  userId: string,
36	  payload: { title: string; body: string; data: Record<string, unknown> },
37	): Promise<void> {
38	  const { data: subs } = await admin
39	    .from("v2_push_subscriptions")
40	    .select("endpoint, p256dh, auth")
41	    .eq("user_id", userId);
42	  if (!subs?.length) return;
43	
44	  const body = JSON.stringify(payload);
45	  const results = await Promise.allSettled(
46	    subs.map((s) =>
47	      webpush.sendNotification(
48	        { endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } },
49	        body,
50	      ),
51	    ),
52	  );
53	
54	  // Clean up subscriptions the browser has dropped (410 Gone).
55	  const gone = results
56	    .map((r, i) =>
57	      r.status === "rejected" &&
58	      (r.reason as { statusCode?: number })?.statusCode === 410
59	        ? subs[i].endpoint
60	        : null,
61	    )
62	    .filter(Boolean) as string[];
63	  if (gone.length) {
64	    await admin
65	      .from("v2_push_subscriptions")
66	      .delete()
67	      .eq("user_id", userId)
68	      .in("endpoint", gone);
69	  }
70	}
71	
72	/** Notify many users at once: insert rows + push. */
73	export async function sendV2Notifications(
74	  admin: SupabaseClient,
75	  userIds: string[],
76	  input: V2NotificationInput,
77	): Promise<void> {
78	  const ids = [...new Set(userIds)].filter(Boolean);
79	  if (ids.length === 0) return;
80	
81	  // Honor per-user prefs (opt-out): a disabled type suppresses the in-app row AND
82	  // the push; master-push-off suppresses only the device push (in-app still logs).
83	  const { inApp, push } = await resolveNotificationRecipients(admin, ids, input.type, input.orgId);
84	
85	  if (inApp.length > 0) {
86	    await admin.from("v2_notifications").insert(
87	      inApp.map((user_id) => ({
88	        org_id: input.orgId,
89	        user_id,
90	        type: input.type,
91	        title: input.title,
92	        body: input.body ?? null,
93	        data: input.data ?? {},
94	      })),
95	    );
96	  }
97	
98	  if (push.length > 0) {
99	    const payload = {
100	      title: input.title,
101	      body: input.body ?? "",
102	      data: input.data ?? {},
103	    };
104	    await Promise.allSettled(push.map((id) => pushToUser(admin, id, payload)));
105	  }
106	}
107	
108	/** Notify a single user. */
109	export async function sendV2Notification(
110	  admin: SupabaseClient,
111	  userId: string,
112	  input: V2NotificationInput,
113	): Promise<void> {
114	  await sendV2Notifications(admin, [userId], input);
115	}
