1	import type { SupabaseClient } from "@supabase/supabase-js";
2	
3	/**
4	 * Granular notification preferences (Twitter-style): a master push toggle plus a
5	 * per-event-type toggle, grouped into sections. Opt-out — a missing pref row
6	 * means enabled.
7	 *
8	 * Two axes:
9	 *   - Per-type toggle  → whether you're notified about that event AT ALL
10	 *                        (governs both the in-app row and the push).
11	 *   - Master push      → whether enabled notifications also buzz your device.
12	 *                        Off = in-app only.
13	 *
14	 * Stored in v2_notification_prefs.category as the type key (e.g. "chat_mention")
15	 * or the special PUSH_MASTER_KEY. Add a type here (mapping it in a section) as new
16	 * producers ship — the settings modal + enforcement pick it up automatically.
17	 */
18	
19	export const PUSH_MASTER_KEY = "push_master";
20	
21	export interface NotificationTypeItem {
22	  type: string;
23	  label: string;
24	  description: string;
25	}
26	export interface NotificationSection {
27	  key: string;
28	  label: string;
29	  items: NotificationTypeItem[];
30	}
31	
32	export const NOTIFICATION_SECTIONS: NotificationSection[] = [
33	  {
34	    key: "chat",
35	    label: "Chat",
36	    items: [
37	      { type: "chat_message", label: "Messages", description: "New messages in your conversations" },
38	      { type: "chat_mention", label: "Mentions", description: "When someone @mentions you" },
39	    ],
40	  },
41	  {
42	    key: "photos",
43	    label: "Photos",
44	    items: [
45	      { type: "gallery_tag", label: "Photo tags", description: "When you're tagged in a photo" },
46	      { type: "gallery_comment", label: "Photo comments", description: "Comments on a photo you're on" },
47	    ],
48	  },
49	  {
50	    key: "articles",
51	    label: "Articles",
52	    items: [{ type: "article", label: "New articles", description: "When a new article is published" }],
53	  },
54	  {
55	    key: "rounds",
56	    label: "My Rounds",
57	    items: [
58	      { type: "round_invite", label: "Round invites", description: "When someone adds you to a round" },
59	      { type: "round_comment", label: "Round comments", description: "Comments on a round you're playing" },
60	      { type: "round_mention", label: "Round mentions", description: "When someone @mentions you in a round comment" },
61	    ],
62	  },
63	  {
64	    // Global mute per type. A follower gets a spectator notification only when
65	    // BOTH the per-follow toggle is on AND the type isn't muted here.
66	    key: "following",
67	    label: "Members you follow",
68	    items: [
69	      { type: "notify_round_started", label: "Round started", description: "When someone you follow tees off" },
70	      { type: "notify_hole_completed", label: "Hole-by-hole", description: "Live scores as someone you follow plays" },
71	      { type: "notify_round_completed", label: "Round finished", description: "When someone you follow finishes a round" },
72	    ],
73	  },
74	];
75	
76	export const NOTIFICATION_TYPE_KEYS = NOTIFICATION_SECTIONS.flatMap((s) => s.items.map((i) => i.type));
77	export const NOTIFICATION_PREF_KEYS = [PUSH_MASTER_KEY, ...NOTIFICATION_TYPE_KEYS];
78	
79	/**
80	 * Split recipients into who gets the in-app row vs the device push for a given
81	 * notification type, honoring prefs (opt-out):
82	 *   - inApp = users who haven't turned this type off.
83	 *   - push  = inApp users who also haven't turned master push off.
84	 * Uncategorized types have no per-type toggle → always in-app; push still
85	 * respects master. Best-effort: on error, deliver to everyone on both channels.
86	 */
87	export async function resolveNotificationRecipients(
88	  admin: SupabaseClient,
89	  userIds: string[],
90	  type: string,
91	  orgId: string,
92	): Promise<{ inApp: string[]; push: string[] }> {
93	  if (userIds.length === 0) return { inApp: [], push: [] };
94	  try {
95	    const { data } = await admin
96	      .from("v2_notification_prefs")
97	      .select("user_id, category")
98	      .eq("org_id", orgId)
99	      .eq("enabled", false)
100	      .in("category", [type, PUSH_MASTER_KEY])
101	      .in("user_id", userIds);
102	    const typeOff = new Set<string>();
103	    const pushOff = new Set<string>();
104	    for (const r of data || []) {
105	      if (r.category === PUSH_MASTER_KEY) pushOff.add(r.user_id as string);
106	      else typeOff.add(r.user_id as string);
107	    }
108	    const inApp = userIds.filter((u) => !typeOff.has(u));
109	    const push = inApp.filter((u) => !pushOff.has(u));
110	    return { inApp, push };
111	  } catch {
112	    return { inApp: userIds, push: userIds };
113	  }
114	}
