5	/** A contest's participants with display info (#209). Any org member may read. */
6	export async function GET(request: Request, { params }: { params: Promise<{ id: string; contestId: string }> }) {
7	  const { userId } = await v2GetUser(request);
8	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
9	  const { id: orgId, contestId } = await params;
10	
11	  const admin = v2AdminClient();
12	  if (!(await isOrgMember(admin, userId, orgId))) {
13	    return NextResponse.json({ error: "Not a member" }, { status: 403 });
14	  }
15	
16	  const { data, error } = await admin
17	    .from("v2_contest_participants")
18	    .select("user_id, v2_profiles!inner(id, display_name, first_name, last_name, avatar_url)")
19	    .eq("contest_id", contestId);
20	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
21	
22	  const participants = (data || []).map((r) => {
23	    const p = (r as { v2_profiles: unknown }).v2_profiles as {
24	      id: string; display_name: string | null; first_name: string | null; last_name: string | null; avatar_url: string | null;
25	    };
26	    return { user_id: p.id, display_name: p.display_name, first_name: p.first_name, last_name: p.last_name, avatar_url: p.avatar_url };
27	  });
28	  return NextResponse.json({ participants });
29	}
