1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { isOrgAdmin, isOrgMember } from "@/lib/v2/orgs";
4	import { CONTEST_SELECT, setContestBuyIn, deleteContestCostItems, type Contest } from "@/lib/v2/contests";
5	
6	/** A single event contest (#209). GET any member; PATCH/DELETE org admins. */
7	
8	export async function GET(request: Request, { params }: { params: Promise<{ id: string; eventId: string; contestId: string }> }) {
9	  const { userId } = await v2GetUser(request);
10	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
11	  const { id: orgId, eventId, contestId } = await params;
12	
13	  const admin = v2AdminClient();
14	  if (!(await isOrgMember(admin, userId, orgId))) {
15	    return NextResponse.json({ error: "Not a member" }, { status: 403 });
16	  }
17	
18	  const { data, error } = await admin
19	    .from("v2_contests").select(CONTEST_SELECT)
20	    .eq("id", contestId).eq("org_id", orgId).eq("event_id", eventId).maybeSingle();
21	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
22	  if (!data) return NextResponse.json({ error: "Not found" }, { status: 404 });
23	  return NextResponse.json({ contest: data });
24	}
25	
26	// Fields an admin may edit directly (scoring_source is set by type on create).
27	// entry_amount_cents is NOT a column — the buy-in lives in v2_cost_items and is
28	// handled separately below via setContestBuyIn (single source of truth, #213).
29	const EDITABLE = new Set([
30	  "name", "contest_date", "start_time", "course_id", "tee_id", "holes", "config", "payout_splits",
31	  "auto_enroll", "declared_no_winner", "status", "sort_order", "winners_locked_at", "winners_locked_by",
32	]);
33	
34	export async function PATCH(request: Request, { params }: { params: Promise<{ id: string; eventId: string; contestId: string }> }) {
35	  const { userId } = await v2GetUser(request);
36	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
37	  const { id: orgId, eventId, contestId } = await params;
38	
39	  const admin = v2AdminClient();
40	  if (!(await isOrgAdmin(admin, userId, orgId))) {
41	    return NextResponse.json({ error: "Admins only" }, { status: 403 });
42	  }
43	
44	  let body: Record<string, unknown>;
45	  try {
46	    body = await request.json();
47	  } catch {
48	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
49	  }
50	
51	  const patch: Record<string, unknown> = {};
52	  for (const [k, v] of Object.entries(body)) if (EDITABLE.has(k)) patch[k] = v;
53	  // The buy-in is stored in v2_cost_items, not on the contest — pull it aside.
54	  const hasBuyIn = "entry_amount_cents" in body;
55	  const buyInCents = hasBuyIn ? (typeof body.entry_amount_cents === "number" ? (body.entry_amount_cents as number) : null) : undefined;
56	  if (Object.keys(patch).length === 0 && !hasBuyIn) return NextResponse.json({ error: "Nothing to update" }, { status: 400 });
57	  if ("name" in patch) {
58	    const name = String(patch.name || "").trim();
59	    if (!name) return NextResponse.json({ error: "Name can't be empty" }, { status: 400 });
60	    patch.name = name;
61	  }
62	
63	  // Apply column edits (if any); otherwise just load the row to sync its buy-in.
64	  let contest: Contest;
65	  if (Object.keys(patch).length > 0) {
66	    patch.updated_at = new Date().toISOString();
67	    const { data, error } = await admin
68	      .from("v2_contests").update(patch)
69	      .eq("id", contestId).eq("org_id", orgId).eq("event_id", eventId)
70	      .select(CONTEST_SELECT).single();
71	    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
72	    contest = data as Contest;
73	  } else {
74	    const { data, error } = await admin
75	      .from("v2_contests").select(CONTEST_SELECT)
76	      .eq("id", contestId).eq("org_id", orgId).eq("event_id", eventId).single();
77	    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
78	    contest = data as Contest;
79	  }
80	
81	  // Sync the buy-in cost item: set the amount when the buy-in changed, otherwise
82	  // (undefined) just carry the new display name onto any existing row.
83	  await setContestBuyIn(admin, contest, hasBuyIn ? buyInCents : undefined);
84	  return NextResponse.json({ contest });
85	}
86	
87	export async function DELETE(request: Request, { params }: { params: Promise<{ id: string; eventId: string; contestId: string }> }) {
88	  const { userId } = await v2GetUser(request);
89	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
90	  const { id: orgId, eventId, contestId } = await params;
91	
92	  const admin = v2AdminClient();
93	  if (!(await isOrgAdmin(admin, userId, orgId))) {
94	    return NextResponse.json({ error: "Admins only" }, { status: 403 });
95	  }
96	
97	  // Un-link any schedule item pointing at this contest (activity_id has no FK).
98	  await admin.from("v2_schedule_items").update({ activity_id: null }).eq("activity_id", contestId);
99	  // Projected buy-in cost items (contest + its children) have no FK — clean up first.
100	  await deleteContestCostItems(admin, contestId);
101	  // Child contests + teams/scores/winners/observations cascade via FK.
102	  const { error } = await admin.from("v2_contests").delete().eq("id", contestId).eq("org_id", orgId).eq("event_id", eventId);
103	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
104	  return NextResponse.json({ ok: true });
105	}
