25	/** Notifications drawer. On open: loads the list, marks all read, and (best-effort)
26	 *  registers the shared push subscription. Tapping an item deep-links via data.url. */
27	export default function NotificationDrawer({
28	  active,
29	  orgId,
30	  onClose,
31	}: {
32	  active: boolean;
33	  orgId: string;
34	  onClose: () => void;
35	}) {
36	  const router = useRouter();
37	  const [items, setItems] = useState<Notif[]>([]);
38	  const [loaded, setLoaded] = useState(false);
39	  const [showSettings, setShowSettings] = useState(false);
40	
41	  // The gear lives in the shell's drawer header (EventShell) and dispatches this.
42	  useEffect(() => {
43	    const openSettings = () => setShowSettings(true);
44	    window.addEventListener("ui:notif-settings", openSettings);
45	    return () => window.removeEventListener("ui:notif-settings", openSettings);
46	  }, []);
47	
48	  const load = useCallback(async () => {
49	    try {
50	      const res = await fetch(`/api/v2/notifications?orgId=${orgId}`);
51	      const d = res.ok ? await res.json() : { notifications: [] };
52	      setItems(d.notifications || []);
53	    } catch {
54	      /* ignore */
55	    } finally {
56	      setLoaded(true);
57	    }
58	  }, [orgId]);
59	
60	  useEffect(() => {
61	    if (!active) return;
62	    load();
63	    // Mark everything read + register for push (both best-effort, gesture = open).
64	    fetch("/api/v2/notifications", {
65	      method: "PATCH",
66	      headers: { "Content-Type": "application/json" },
67	      body: JSON.stringify({ orgId, markAll: true }),
68	    }).catch(() => {});
69	    subscribeToV2Push().catch(() => {});
70	  }, [active, orgId, load]);
71	
72	  // Live list: new notifications appear while the drawer is open (and are marked
73	  // read on arrival, since the user is looking at them). Mirrors the legacy drawer.
74	  useEffect(() => {
75	    if (!active) return;
76	    let cancelled = false;
77	    let sb: Awaited<ReturnType<typeof v2RealtimeClient>> | null = null;
78	    let channel: RealtimeChannel | null = null;
79	    (async () => {
80	      sb = await v2RealtimeClient();
81	      if (cancelled) return;
82	      channel = sb
83	        .channel("v2-notif-drawer")
84	        .on(
85	          "postgres_changes",
86	          { event: "INSERT", schema: "public", table: "v2_notifications" },
87	          (payload) => {
88	            const n = payload.new as Notif & { org_id: string };
89	            if (n.org_id !== orgId || CHAT_TYPES.includes(n.type)) return;
90	            setItems((cur) =>
91	              cur.some((x) => x.id === n.id) ? cur : [{ ...n, read: true }, ...cur],
92	            );
93	            fetch("/api/v2/notifications", {
94	              method: "PATCH",
95	              headers: { "Content-Type": "application/json" },
96	              body: JSON.stringify({ orgId, ids: [n.id] }),
97	            }).catch(() => {});
98	          },
99	        )
100	        .subscribe();
101	    })();
102	    return () => {
103	      cancelled = true;
104	      if (sb && channel) sb.removeChannel(channel);
105	    };
106	  }, [active, orgId]);
107	
108	  function open(n: Notif) {
109	    if (!n.data?.url) return;
110	    // In-app: if the URL targets a drawer (?open=…), open it directly (no nav) so
111	    // it works while already on the home route; otherwise navigate. The push path
112	    // (service worker) uses the same URL to cold-load and open the drawer.
113	    const u = new URL(n.data.url, window.location.origin);
114	    const target = u.searchParams.get("open");
115	    if (target) {
116	      window.dispatchEvent(
117	        new CustomEvent("ui:open-drawer", {
118	          detail: {
119	            name: target,
120	            room: u.searchParams.get("room") ?? undefined,
121	            photo: u.searchParams.get("photo") ?? undefined,
122	            msg: u.searchParams.get("msg") ?? undefined,
123	          },
124	        }),
125	      );
126	    } else {
127	      router.push(n.data.url);
128	    }
129	    onClose();
130	  }
131	
132	  async function remove(id: string, e: React.MouseEvent) {
133	    e.stopPropagation();
134	    setItems((cur) => cur.filter((n) => n.id !== id));
135	    fetch("/api/v2/notifications", {
136	      method: "DELETE",
137	      headers: { "Content-Type": "application/json" },
138	      body: JSON.stringify({ orgId, ids: [id] }),
139	    }).catch(() => {});
140	  }
141	
142	  async function clearAll() {
143	    setItems([]);
144	    fetch("/api/v2/notifications", {
145	      method: "DELETE",
146	      headers: { "Content-Type": "application/json" },
147	      body: JSON.stringify({ orgId, all: true }),
148	    }).catch(() => {});
149	  }
150	
151	  const settings = showSettings ? (
152	    <NotifSettingsModal orgId={orgId} onClose={() => setShowSettings(false)} />
153	  ) : null;
154	
155	  let content: React.ReactNode;
156	  if (!loaded) {
157	    content = <p className={styles.drawerStub}>Loading…</p>;
158	  } else if (items.length === 0) {
159	    content = <p className={styles.drawerStub}>You&apos;re all caught up.</p>;
160	  } else {
161	    content = (
162	      <div className={styles.notifList}>
163	        <button type="button" className={styles.notifClear} onClick={clearAll}>
164	          Clear all
165	        </button>
166	        {items.map((n) => (
167	          <div
168	            key={n.id}
169	            className={styles.notifRow}
170	            data-unread={!n.read || undefined}
171	            data-clickable={!!n.data?.url || undefined}
172	            onClick={() => open(n)}
173	          >
174	            <span className={styles.notifDot} data-type={n.type} aria-hidden />
175	            <span className={styles.notifText}>
176	              <span className={styles.notifTitle}>{n.title}</span>
177	              {n.body && <span className={styles.notifBody}>{n.body}</span>}
178	              <span className={styles.notifTime}>{timeAgo(n.created_at)}</span>
179	            </span>
180	            <button
181	              type="button"
182	              className={styles.notifDelete}
183	              onClick={(e) => remove(n.id, e)}
184	              aria-label="Dismiss"
185	            >
186	              ×
187	            </button>
188	          </div>
189	        ))}
190	      </div>
191	    );
192	  }
193	
194	  return (
195	    <>
196	      {content}
197	      {settings}
198	    </>
199	  );
200	}
