202	/** Modal (launched from the drawer-header gear) to toggle notification
203	 *  categories. Opt-out: everything defaults on. Toggles save immediately. */
204	function NotifSettingsModal({ orgId, onClose }: { orgId: string; onClose: () => void }) {
205	  const [prefs, setPrefs] = useState<Record<string, boolean> | null>(null);
206	
207	  useEffect(() => {
208	    let cancelled = false;
209	    (async () => {
210	      const res = await fetch(`/api/v2/notifications/prefs?orgId=${orgId}`);
211	      const d = res.ok ? await res.json() : { prefs: {} };
212	      if (!cancelled) setPrefs(d.prefs || {});
213	    })();
214	    return () => {
215	      cancelled = true;
216	    };
217	  }, [orgId]);
218	
219	  useEffect(() => {
220	    const onKey = (e: KeyboardEvent) => {
221	      if (e.key === "Escape") onClose();
222	    };
223	    window.addEventListener("keydown", onKey);
224	    return () => window.removeEventListener("keydown", onKey);
225	  }, [onClose]);
226	
227	  function toggle(key: string, next: boolean) {
228	    setPrefs((p) => ({ ...(p || {}), [key]: next }));
229	    fetch("/api/v2/notifications/prefs", {
230	      method: "PUT",
231	      headers: { "Content-Type": "application/json" },
232	      body: JSON.stringify({ orgId, category: key, enabled: next }),
233	    }).catch(() => {});
234	  }
235	
236	  if (typeof document === "undefined") return null;
237	  // Portal into the /new theme root (.wrap) — NOT document.body — so the org
238	  // CSS variables (--card/--ink/--brand/--line) resolve. body is outside that
239	  // scope, which would render the card transparent and hide the toggle tracks.
240	  const host = document.querySelector<HTMLElement>(`.${styles.wrap}`) ?? document.body;
241	
242	  return createPortal(
243	    <div className={styles.notifSettingsBackdrop} onClick={onClose}>
244	      <div className={styles.notifSettingsCard} role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}>
245	        <div className={styles.notifSettingsHead}>
246	          <span className={styles.notifSettingsTitle}>Notification Settings</span>
247	          <button type="button" className={styles.notifSettingsClose} onClick={onClose} aria-label="Close">
248	            <svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24">
249	              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
250	            </svg>
251	          </button>
252	        </div>
253	        <p className={styles.notifSettingsIntro}>
254	          Choose what you&apos;re notified about. Turning a type off hides it everywhere; turning off
255	          Push notifications keeps everything in-app only.
256	        </p>
257	        {prefs === null ? (
258	          <p className={styles.notifSettingsLoading}>Loading…</p>
259	        ) : (
260	          <div className={styles.notifSettingsList}>
261	            {/* Master push toggle */}
262	            <div className={styles.notifSettingRow}>
263	              <span className={styles.notifSettingText}>
264	                <span className={styles.notifSettingLabel}>Push notifications</span>
265	                <span className={styles.notifSettingDesc}>Also buzz this device. Off = in-app only.</span>
266	              </span>
267	              <Switch on={prefs[PUSH_MASTER_KEY] ?? true} label="Push notifications" onToggle={(v) => toggle(PUSH_MASTER_KEY, v)} />
268	            </div>
269	
270	            {NOTIFICATION_SECTIONS.map((section) => (
271	              <div key={section.key} className={styles.notifSettingsSection}>
272	                <p className={styles.notifSettingsSectionLabel}>{section.label}</p>
273	                {section.items.map((item) => {
274	                  const on = prefs[item.type] ?? true;
275	                  return (
276	                    <div key={item.type} className={styles.notifSettingRow}>
277	                      <span className={styles.notifSettingText}>
278	                        <span className={styles.notifSettingLabel}>{item.label}</span>
279	                        <span className={styles.notifSettingDesc}>{item.description}</span>
280	                      </span>
281	                      <Switch on={on} label={item.label} onToggle={(v) => toggle(item.type, v)} />
282	                    </div>
283	                  );
284	                })}
285	              </div>
286	            ))}
287	          </div>
288	        )}
289	      </div>
290	    </div>,
291	    host,
292	  );
293	}
