295	/** Small on/off switch used throughout the settings modal. */
296	function Switch({ on, label, onToggle }: { on: boolean; label: string; onToggle: (next: boolean) => void }) {
297	  return (
298	    <button
299	      type="button"
300	      role="switch"
301	      aria-checked={on}
302	      aria-label={label}
303	      className={styles.notifSwitch}
304	      data-on={on || undefined}
305	      onClick={() => onToggle(!on)}
306	    >
307	      <span className={styles.notifSwitchKnob} />
308	    </button>
309	  );
310	}
