1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { isOrgMember } from "@/lib/v2/orgs";
4	import { NOTIFICATION_PREF_KEYS } from "@/lib/v2/notification-prefs";
5	
6	/**
7	 * Per-user notification preferences for an org (opt-out; missing row = enabled).
8	 *   GET ?orgId=       — { prefs: { <key>: boolean } } for every pref key
9	 *                        (push_master + each notification type).
10	 *   PUT { orgId, category, enabled } — upsert one toggle (`category` = a pref key).
11	 * Auth: bearer/cookie; org-membership gated.
12	 */
13	const VALID = new Set(NOTIFICATION_PREF_KEYS);
14	
15	export async function GET(request: Request) {
16	  const orgId = new URL(request.url).searchParams.get("orgId");
17	  const { userId } = await v2GetUser(request);
18	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
19	  if (!orgId) return NextResponse.json({ error: "orgId required" }, { status: 400 });
20	
21	  const admin = v2AdminClient();
22	  if (!(await isOrgMember(admin, userId, orgId))) {
23	    return NextResponse.json({ error: "Not a member" }, { status: 403 });
24	  }
25	
26	  const { data } = await admin
27	    .from("v2_notification_prefs")
28	    .select("category, enabled")
29	    .eq("org_id", orgId)
30	    .eq("user_id", userId);
31	  const overrides = new Map((data || []).map((r) => [r.category as string, r.enabled as boolean]));
32	
33	  // Default every pref key to enabled; apply stored overrides.
34	  const prefs: Record<string, boolean> = {};
35	  for (const key of NOTIFICATION_PREF_KEYS) prefs[key] = overrides.get(key) ?? true;
36	
37	  return NextResponse.json({ prefs });
38	}
39	
40	export async function PUT(request: Request) {
41	  const { userId } = await v2GetUser(request);
42	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
43	
44	  let body: { orgId?: string; category?: string; enabled?: boolean };
45	  try {
46	    body = await request.json();
47	  } catch {
48	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
49	  }
50	  if (!body.orgId || !body.category || typeof body.enabled !== "boolean") {
51	    return NextResponse.json({ error: "orgId, category, enabled required" }, { status: 400 });
52	  }
53	  if (!VALID.has(body.category)) {
54	    return NextResponse.json({ error: "Unknown category" }, { status: 400 });
55	  }
56	
57	  const admin = v2AdminClient();
58	  if (!(await isOrgMember(admin, userId, body.orgId))) {
59	    return NextResponse.json({ error: "Not a member" }, { status: 403 });
60	  }
61	
62	  const { error } = await admin.from("v2_notification_prefs").upsert(
63	    {
64	      user_id: userId,
65	      org_id: body.orgId,
66	      category: body.category,
67	      enabled: body.enabled,
68	      updated_at: new Date().toISOString(),
69	    },
70	    { onConflict: "user_id,org_id,category" },
71	  );
72	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
73	
74	  return NextResponse.json({ ok: true });
75	}
