1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { isOrgMember } from "@/lib/v2/orgs";
4	
5	/**
6	 * The caller's notifications for one org.
7	 *   GET    ?orgId=  — recent notifications + unread count (chat types excluded,
8	 *                     matching the legacy drawer; chat surfaces its own).
9	 *   PATCH  { orgId, ids?[] | markAll } — mark read.
10	 *   DELETE { orgId, ids?[] | all }     — delete.
11	 * Auth: bearer (native) or cookie (web). A user only ever touches their OWN rows.
12	 */
13	
14	const CHAT_TYPES = ["chat_message", "chat_mention"];
15	
16	async function auth(request: Request, orgId: string | null) {
17	  const { userId } = await v2GetUser(request);
18	  if (!userId) return { error: "Not authenticated", status: 401 as const };
19	  if (!orgId) return { error: "orgId required", status: 400 as const };
20	  const admin = v2AdminClient();
21	  if (!(await isOrgMember(admin, userId, orgId))) {
22	    return { error: "Not a member", status: 403 as const };
23	  }
24	  return { admin, userId };
25	}
26	
27	export async function GET(request: Request) {
28	  const orgId = new URL(request.url).searchParams.get("orgId");
29	  const a = await auth(request, orgId);
30	  if ("error" in a) return NextResponse.json({ error: a.error }, { status: a.status });
31	
32	  const [listRes, countRes] = await Promise.all([
33	    a.admin
34	      .from("v2_notifications")
35	      .select("id, type, title, body, data, read, created_at")
36	      .eq("user_id", a.userId)
37	      .eq("org_id", orgId)
38	      .not("type", "in", `(${CHAT_TYPES.join(",")})`)
39	      .order("created_at", { ascending: false })
40	      .limit(40),
41	    a.admin
42	      .from("v2_notifications")
43	      .select("id", { count: "exact", head: true })
44	      .eq("user_id", a.userId)
45	      .eq("org_id", orgId)
46	      .eq("read", false)
47	      .not("type", "in", `(${CHAT_TYPES.join(",")})`),
48	  ]);
49	
50	  return NextResponse.json({
51	    notifications: listRes.data || [],
52	    unread: countRes.count ?? 0,
53	  });
54	}
55	
56	export async function PATCH(request: Request) {
57	  let body: { orgId?: string; ids?: string[]; markAll?: boolean };
58	  try {
59	    body = await request.json();
60	  } catch {
61	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
62	  }
63	  const a = await auth(request, body.orgId ?? null);
64	  if ("error" in a) return NextResponse.json({ error: a.error }, { status: a.status });
65	
66	  let q = a.admin
67	    .from("v2_notifications")
68	    .update({ read: true })
69	    .eq("user_id", a.userId)
70	    .eq("org_id", body.orgId!);
71	  if (!body.markAll) {
72	    if (!body.ids?.length) return NextResponse.json({ error: "ids required" }, { status: 400 });
73	    q = q.in("id", body.ids);
74	  }
75	  const { error } = await q;
76	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
77	  return NextResponse.json({ ok: true });
78	}
79	
80	export async function DELETE(request: Request) {
81	  let body: { orgId?: string; ids?: string[]; all?: boolean };
82	  try {
83	    body = await request.json();
84	  } catch {
85	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
86	  }
87	  const a = await auth(request, body.orgId ?? null);
88	  if ("error" in a) return NextResponse.json({ error: a.error }, { status: a.status });
89	
90	  let q = a.admin
91	    .from("v2_notifications")
92	    .delete()
93	    .eq("user_id", a.userId)
94	    .eq("org_id", body.orgId!);
95	  if (!body.all) {
96	    if (!body.ids?.length) return NextResponse.json({ error: "ids required" }, { status: 400 });
97	    q = q.in("id", body.ids);
98	  }
99	  const { error } = await q;
100	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
101	  return NextResponse.json({ ok: true });
102	}
