102	export function normalizeHostname(input: string): string | null {
103	  let h = input.trim().toLowerCase();
104	  h = h.replace(/^https?:\/\//, "");
105	  h = h.split("/")[0];
106	  h = h.replace(/\.$/, "");
107	  if (!/^(?=.{1,253}$)([a-z0-9](-*[a-z0-9])*\.)+[a-z]{2,}$/.test(h)) return null;
