8	/**
9	 * RSVP for an event. Mirrors the legacy model: a member sets their attendance
10	 * *likelihood* (25/50/75/99). 99 ("Attending") marks them on_roster. DELETE
11	 * clears the RSVP. Returns the caller's likelihood plus the attending count
12	 * (on_roster). Auth: bearer (native) or cookie (web). Membership-gated.
13	 *
14	 * NOTE: the legacy site also cascades contest/roster enrollment on attend/leave.
15	 * v2 has no contest system yet, so we only persist likelihood + on_roster here;
16	 * enrollment sync lands when v2 contests do.
17	 */
18	
19	const LIKELIHOODS = [25, 50, 75, 99];
20	const LIKELIHOOD_LABEL: Record<number, string> = {
21	  99: "Attending",
22	  75: "Probable",
23	  50: "Questionable",
24	  25: "Doubtful",
25	};
