27	async function resolve(request: Request, eventId: string) {
28	  const { userId } = await v2GetUser(request);
29	  if (!userId) return { error: "Not authenticated", status: 401 as const };
30	  const admin = v2AdminClient();
31	  const { data: event } = await admin
32	    .from("v2_events")
33	    .select("id, org_id")
34	    .eq("id", eventId)
35	    .maybeSingle();
36	  if (!event) return { error: "Event not found", status: 404 as const };
37	  if (!(await isOrgMember(admin, userId, event.org_id))) {
38	    return { error: "Not a member", status: 403 as const };
39	  }
40	  return { admin, userId, orgId: event.org_id as string };
41	}
