55	export async function GET(
56	  request: Request,
57	  { params }: { params: Promise<{ eventId: string }> },
58	) {
59	  const { eventId } = await params;
60	  const g = await resolve(request, eventId);
61	  if ("error" in g) return NextResponse.json({ error: g.error }, { status: g.status });
62	
63	  const [{ data }, mode] = await Promise.all([
64	    g.admin
65	      .from("v2_event_participants")
66	      .select("user_id, likelihood, likelihood_set_at, on_roster, user:v2_profiles(display_name, first_name, last_name, avatar_url)")
67	      .eq("event_id", eventId),
68	    orgNameMode(g.admin, g.orgId),
69	  ]);
70	
71	  const rows = (data || []).map((r) => {
72	    const u = Array.isArray(r.user) ? r.user[0] : r.user;
73	    return {
74	      userId: r.user_id as string,
75	      likelihood: r.likelihood as number,
76	      likelihoodSetAt: (r.likelihood_set_at as string | null) ?? null,
77	      displayName: pickName(u, mode),
78	      avatarUrl: (u?.avatar_url as string | null) ?? null,
79	    };
80	  });
81	
82	  const mine = rows.find((r) => r.userId === g.userId);
83	  return NextResponse.json({
84	    likelihood: mine?.likelihood ?? null,
85	    attendingCount: (data || []).filter((r) => r.on_roster).length,
