91	export async function POST(
92	  request: Request,
93	  { params }: { params: Promise<{ eventId: string }> },
94	) {
95	  const { eventId } = await params;
96	  const g = await resolve(request, eventId);
97	  if ("error" in g) return NextResponse.json({ error: g.error }, { status: g.status });
98	
99	  let body: { likelihood?: number };
100	  try {
101	    body = await request.json();
102	  } catch {
103	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
104	  }
105	  const likelihood = body.likelihood;
106	  if (!LIKELIHOODS.includes(likelihood as number)) {
107	    return NextResponse.json(
108	      { error: "likelihood must be 25, 50, 75, or 99" },
109	      { status: 400 },
110	    );
111	  }
112	  const onRoster = likelihood === 99;
113	
114	  // Pre-read prior likelihood so we log only a *genuine change* (not a re-confirm
115	  // of the same level). Any move between levels is feed-worthy.
116	  const { data: prior } = await g.admin
117	    .from("v2_event_participants")
118	    .select("likelihood")
119	    .eq("event_id", eventId)
120	    .eq("user_id", g.userId)
121	    .maybeSingle();
122	  const priorLikelihood = (prior?.likelihood as number | undefined) ?? null;
123	
124	  const { error } = await g.admin.from("v2_event_participants").upsert(
125	    {
126	      event_id: eventId,
127	      org_id: g.orgId,
128	      user_id: g.userId,
129	      likelihood,
130	      on_roster: onRoster,
131	      likelihood_set_at: new Date().toISOString(),
132	      updated_at: new Date().toISOString(),
133	    },
134	    { onConflict: "event_id,user_id" },
135	  );
136	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
137	
138	  // Managed event channel: opting in (on_roster) adds you with full history;
139	  // dropping below "Attending" removes you (your past messages stay). Best-effort.
140	  await syncEventChannelMembership(g.admin, eventId, g.userId, onRoster).catch(() => {});
141	
142	  // Activity feed: a row per genuine likelihood change. Title is the status only
143	  // ("Attending 99%") — the feed renders the actor's name + avatar itself.
144	  if (priorLikelihood !== likelihood) {
145	    await logActivity(g.admin, {
146	      orgId: g.orgId,
147	      eventId,
148	      kind: "rsvp",
149	      actorId: g.userId,
150	      title: `${LIKELIHOOD_LABEL[likelihood as number]} ${likelihood}%`,
151	      refId: eventId,
152	      metadata: { likelihood },
153	    }).catch(() => {});
154	  }
155	
156	  return NextResponse.json({
157	    likelihood,
158	    attendingCount: await attendingCount(g.admin, eventId),
159	  });
160	}
