4	const PROFILE = "id, display_name, first_name, last_name, nickname, avatar_url, city, state, is_founder, sponsor_id, birthdate, playing_since, occupation, swings, typical_shot, shirt_size, fun_fact, best_shot";
5	const REF = "id, display_name, first_name, last_name, nickname, avatar_url";
6	
7	/**
8	 * GET /api/v2/members/[id]?orgId= — one member's public detail for the directory:
9	 * profile + sponsor + who they sponsor + accolades + handicap + events-attended,
10	 * plus the viewer's follow state (and per-follow toggles).
11	 */
12	export async function GET(request: Request, { params }: { params: Promise<{ id: string }> }) {
13	  const { userId } = await v2GetUser(request);
14	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
15	  const { id } = await params;
16	  const orgId = new URL(request.url).searchParams.get("orgId");
17	
18	  const admin = v2AdminClient();
19	  const { data: member } = await admin.from("v2_profiles").select(PROFILE).eq("id", id).maybeSingle();
20	  if (!member) return NextResponse.json({ error: "Member not found" }, { status: 404 });
21	
22	  const [{ data: sponsorRow }, { data: descendants }, { data: accolades }, { data: hcap }, follow] = await Promise.all([
23	    member.sponsor_id
24	      ? admin.from("v2_profiles").select(REF).eq("id", member.sponsor_id).maybeSingle()
25	      : Promise.resolve({ data: null }),
26	    admin.from("v2_profiles").select(REF).eq("sponsor_id", id).order("display_name"),
27	    admin.from("v2_accolades").select("title, year").eq("user_id", id).order("year", { ascending: false }),
28	    admin.from("v2_player_handicaps").select("handicap_index").eq("user_id", id).maybeSingle(),
29	    admin
30	      .from("v2_user_favorites")
31	      .select("notify_round_started, notify_hole_completed, notify_round_completed")
32	      .eq("follower_id", userId)
33	      .eq("favorite_user_id", id)
34	      .maybeSingle(),
35	  ]);
36	
37	  // archived (inactive) state is per-org, on the membership — orthogonal to status.
38	  let archived = false;
39	  if (orgId) {
40	    const { data: mem } = await admin
41	      .from("v2_memberships")
42	      .select("archived_at")
43	      .eq("org_id", orgId)
44	      .eq("user_id", id)
45	      .maybeSingle();
46	    archived = !!(mem?.archived_at as string | null);
47	  }
48	
49	  // events-attended within the org (non-declined RSVPs).
50	  let eventsAttended = 0;
51	  if (orgId) {
52	    const { data: evs } = await admin.from("v2_events").select("id").eq("org_id", orgId);
53	    const ids = (evs || []).map((e) => e.id);
54	    if (ids.length) {
55	      const { count } = await admin
56	        .from("v2_event_participants")
57	        .select("event_id", { count: "exact", head: true })
58	        .eq("user_id", id)
59	        .neq("status", "not_going")
60	        .in("event_id", ids);
61	      eventsAttended = count ?? 0;
62	    }
63	  }
64	
65	  return NextResponse.json({
66	    member,
67	    sponsor: sponsorRow ?? null,
68	    descendants: descendants || [],
69	    accolades: accolades || [],
70	    handicap: (hcap?.handicap_index as number | null) ?? null,
71	    eventsAttended,
72	    archived,
73	    isFollowing: !!follow.data,
74	    followToggles: follow.data ?? null,
75	  });
76	}
